public void Nakagin_Capsule_Tower_Copy_Paste_Roundtrip()
{
    var kit = Tests.LoadAsset<Kit>("metabolism.kit.semio.json");
    var design = kit.Designs.First(d => d.Name == "Nakagin Capsule Tower" && d.Parent == null);
    var selection = Tests.LoadAsset<Selection>("nakagin-capsule-tower.copy.design.selection.semio.json");

    var pieceGuids = selection.Pieces.Select(p => p.Guid).ToList();
    var connectionGuids = selection.Connections.Select(c => c.Guid).ToList();

    // Test CopyDesign
    var copyDesign = Design.CopyDesign(kit, design, pieceGuids, connectionGuids);

    // Load or generate expected copy design
    var expectedCopy = Tests.LoadAsset<Design>("nakagin-capsule-tower.copy.design.semio.json");

    // Verify piece count
    Assert.Equal(expectedCopy.Pieces.Count, copyDesign.Pieces.Count);

    // Verify connection count
    Assert.Equal(expectedCopy.Connections.Count, copyDesign.Connections.Count);

    // Verify each piece exists in the copy
    var copyPieceGuids = new HashSet<string>(copyDesign.Pieces.Select(p => p.Guid));
    var expectedPieceGuids = new HashSet<string>(expectedCopy.Pieces.Select(p => p.Guid));
    foreach (var g in expectedPieceGuids)
        Assert.True(copyPieceGuids.Contains(g), $"Expected piece {g} not found in copy output");

    // Verify external pieces have semio.piece.origin attribute
    foreach (var p in copyDesign.Pieces)
    {
        var expectedPiece = expectedCopy.Pieces.FirstOrDefault(ep => ep.Guid == p.Guid);
        Assert.NotNull(expectedPiece);
        var hasOriginAttr = p.Attributes.Any(a => a.Key == "semio.piece.origin" && a.Value == "external");
        var expectedOriginAttr = expectedPiece!.Attributes.Any(a => a.Key == "semio.piece.origin" && a.Value == "external");
        Assert.Equal(expectedOriginAttr, hasOriginAttr);
    }

    // Verify pp_excl_pc_incl pieces have semio.center and semio.plane attributes
    foreach (var p in copyDesign.Pieces)
    {
        var expectedPiece = expectedCopy.Pieces.First(ep => ep.Guid == p.Guid);
        var hasCenterAttr = p.Attributes.Any(a => a.Key == "semio.center");
        var expectedCenterAttr = expectedPiece.Attributes.Any(a => a.Key == "semio.center");
        Assert.Equal(expectedCenterAttr, hasCenterAttr);
        var hasPlaneAttr = p.Attributes.Any(a => a.Key == "semio.plane");
        var expectedPlaneAttr = expectedPiece.Attributes.Any(a => a.Key == "semio.plane");
        Assert.Equal(expectedPlaneAttr, hasPlaneAttr);
    }

    // Verify connections are in expected set
    var copyConnGuids = new HashSet<string>(copyDesign.Connections.Select(c => c.Guid));
    var expectedConnGuids = new HashSet<string>(expectedCopy.Connections.Select(c => c.Guid));
    foreach (var g in expectedConnGuids)
        Assert.True(copyConnGuids.Contains(g), $"Expected connection {g} not found in copy output");

    // Test PasteDesign with original anchoring (no coord)
    var pasteDiff = Design.PasteDesign(kit, copyDesign, design, "original");
    Assert.NotNull(pasteDiff.Pieces);
    Assert.NotNull(pasteDiff.Pieces!.Added);

    // Verify pasted pieces don't include external-origin pieces
    foreach (var addedPiece in pasteDiff.Pieces.Added)
    {
        Assert.False(addedPiece.Attributes.Any(a => a.Key == "semio.piece.origin" && a.Value == "external"),
            $"External-origin piece {addedPiece.Guid} should not be in paste output");
    }

    // Verify pasted connections exist
    Assert.NotNull(pasteDiff.Connections);
    Assert.NotNull(pasteDiff.Connections!.Added);

    // Apply paste diff to target to get the paste design
    var pasteDesignResult = Design.ApplyDiff(Entity<Design>.DeepClone(design)!, pasteDiff);

    // Test PasteDesign with coord
    var pasteWithCoordDiff = Design.PasteDesign(kit, copyDesign, design, "original", new Coord { U = 10, V = 10 });
    Assert.NotNull(pasteWithCoordDiff.Pieces);
    Assert.NotNull(pasteWithCoordDiff.Pieces!.Added);

    // Verify with-coord pasted pieces don't include external-origin pieces
    foreach (var addedPiece in pasteWithCoordDiff.Pieces.Added)
    {
        Assert.False(addedPiece.Attributes.Any(a => a.Key == "semio.piece.origin" && a.Value == "external"),
            $"External-origin piece {addedPiece.Guid} should not be in paste with-coord output");
    }

    // Verify with-coord pasted connections exist
    Assert.NotNull(pasteWithCoordDiff.Connections);
    Assert.NotNull(pasteWithCoordDiff.Connections!.Added);

