import type { Design, DesignChange, DesignDiff } from "@semio/js";
import { applyDesignDiff } from "@semio/js";
import type { Meta, StoryObj } from "@storybook/react";
import * as React from "react";

import { AlgorithmApp, WindowKind, type AlgorithmContextValue, type AlgorithmWindowDef, type VecValue } from "../../index";
import { nativeCopyDesign, nativeFlattenDesign, nativePasteDesign, type NativeAlgorithmLanguage } from "../../nativeAlgorithmAdapter";
import { useAlgorithmLanguage } from "../withLanguage";

import metabolismKit from "../../../assets/semio/metabolism.kit.semio.json";
import { NakaginCapsuleTowerCopySelection } from "../../../assets/index";

const nakaginCapsuleTowerDesignGuid = "9a890dd4-0a9c-48ac-920a-9e62666465ef";
const rawDesign = (metabolismKit.designs ?? []).find((d: any) => d.guid === nakaginCapsuleTowerDesignGuid) as any;

const selectionPieceGuids = ((NakaginCapsuleTowerCopySelection as any).pieces ?? []).map((p: any) => p.guid) as string[];
const selectionConnectionGuids = ((NakaginCapsuleTowerCopySelection as any).connections ?? []).map((c: any) => c.guid) as string[];

// #region WithoutCoord

const WITHOUT_COORD_WINDOWS: AlgorithmWindowDef[] = [
  { id: "copypaste-input", kind: WindowKind.SELECTION_INPUT, label: "Input" },
  { id: "copypaste-diff", kind: WindowKind.DESIGN_DIFF_OUTPUT, label: "Paste Diff" },
];

function CopyAndPasteWithoutCoordFrame() {
  const language = useAlgorithmLanguage() as NativeAlgorithmLanguage;
  const kit = metabolismKit as any;
  const [flattenChange, setFlattenChange] = React.useState<DesignChange | null>(null);
  const [baseDesign, setBaseDesign] = React.useState<any | null>(null);
  const [selectedPieceGuids, setSelectedPieceGuids] = React.useState<string[]>(selectionPieceGuids);
  const [selectedConnectionGuids, setSelectedConnectionGuids] = React.useState<string[]>(selectionConnectionGuids);
  const [designDiff, setDesignDiff] = React.useState<DesignDiff | undefined>(undefined);

  React.useEffect(() => {
    let cancelled = false;
    setFlattenChange(null);
    setBaseDesign(null);
    setDesignDiff(undefined);
    void (async () => {
      const fc = await nativeFlattenDesign(kit, rawDesign.guid, language);
      if (cancelled) return;
      setFlattenChange(fc);
      const bd = applyDesignDiff(rawDesign, fc.forward) as any;
      setBaseDesign(bd);
    })();
    return () => { cancelled = true; };
  }, [kit, language]);

  React.useEffect(() => {
    if (!baseDesign) return;
    let cancelled = false;
    void (async () => {
      if (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) {
        if (!cancelled) setDesignDiff(undefined);
        return;
      }
      setDesignDiff(undefined);
      const copied = await nativeCopyDesign(kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, language);
      if (cancelled) return;
      const diff = await nativePasteDesign(kit, copied, baseDesign, "original", undefined, language);
      if (!cancelled) setDesignDiff(diff);
    })();
    return () => { cancelled = true; };
  }, [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, language]);

  const outputDesign = React.useMemo(() => (designDiff && baseDesign ? applyDesignDiff(baseDesign, designDiff) as Design : (baseDesign ?? rawDesign)), [designDiff, baseDesign]);

  const context: AlgorithmContextValue = React.useMemo(
    () => ({
      kit,
      design: baseDesign ?? rawDesign,
      selectedPieceGuids,
      onSelectedPieceGuidsChange: setSelectedPieceGuids,
      selectedConnectionGuids,
      onSelectedConnectionGuidsChange: setSelectedConnectionGuids,
      designDiff,
      outputDesign,
      error: !flattenChange || !baseDesign ? `Loading copy & paste preview (${language})…` : (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) ? "Select at least one piece or connection to copy." : !designDiff ? `Loading paste result (${language})…` : undefined,
    }),
    [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, designDiff, outputDesign, flattenChange, language],
  );

  return <AlgorithmApp id="copypaste" label="Copy & Paste" windows={WITHOUT_COORD_WINDOWS} context={context} className="h-full w-full" />;
}

// #endregion WithoutCoord

// #region WithCoord

const WITH_COORD_WINDOWS: AlgorithmWindowDef[] = [
  { id: "copypaste-vec", kind: WindowKind.VEC_INPUT, label: "Coord" },
  { id: "copypaste-input", kind: WindowKind.SELECTION_INPUT, label: "Input" },
  { id: "copypaste-diff", kind: WindowKind.DESIGN_DIFF_OUTPUT, label: "Paste Diff" },
];

function CopyAndPasteWithCoordFrame() {
  const language = useAlgorithmLanguage() as NativeAlgorithmLanguage;
  const kit = metabolismKit as any;
  const [flattenChange, setFlattenChange] = React.useState<DesignChange | null>(null);
  const [baseDesign, setBaseDesign] = React.useState<any | null>(null);
  const [selectedPieceGuids, setSelectedPieceGuids] = React.useState<string[]>(selectionPieceGuids);
  const [selectedConnectionGuids, setSelectedConnectionGuids] = React.useState<string[]>(selectionConnectionGuids);
  const [vec, setVec] = React.useState<VecValue>({ u: 10, v: 10 });
  const [designDiff, setDesignDiff] = React.useState<DesignDiff | undefined>(undefined);

  React.useEffect(() => {
    let cancelled = false;
    setFlattenChange(null);
    setBaseDesign(null);
    setDesignDiff(undefined);
    void (async () => {
      const fc = await nativeFlattenDesign(kit, rawDesign.guid, language);
      if (cancelled) return;
      setFlattenChange(fc);
      const bd = applyDesignDiff(rawDesign, fc.forward) as any;
      setBaseDesign(bd);
    })();
    return () => { cancelled = true; };
  }, [kit, language]);

  React.useEffect(() => {
    if (!baseDesign) return;
    let cancelled = false;
    void (async () => {
      if (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) {
        if (!cancelled) setDesignDiff(undefined);
        return;
      }
      setDesignDiff(undefined);
      const copied = await nativeCopyDesign(kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, language);
      if (cancelled) return;
      const coord = { u: vec.u, v: vec.v };
      const diff = await nativePasteDesign(kit, copied, baseDesign, "original", coord, language);
      if (!cancelled) setDesignDiff(diff);
    })();
    return () => { cancelled = true; };
  }, [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, vec, language]);

  const outputDesign = React.useMemo(() => (designDiff && baseDesign ? applyDesignDiff(baseDesign, designDiff) as Design : (baseDesign ?? rawDesign)), [designDiff, baseDesign]);

  const context: AlgorithmContextValue = React.useMemo(
    () => ({
      kit,
      design: baseDesign ?? rawDesign,
      vec,
      onVecChange: setVec,
      vecMin: { u: -50, v: -50 },
      vecMax: { u: 50, v: 50 },
      selectedPieceGuids,
      onSelectedPieceGuidsChange: setSelectedPieceGuids,
      selectedConnectionGuids,
      onSelectedConnectionGuidsChange: setSelectedConnectionGuids,
      designDiff,
      outputDesign,
      error: !flattenChange || !baseDesign ? `Loading copy & paste preview (${language})…` : (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) ? "Select at least one piece or connection to copy." : !designDiff ? `Loading paste result (${language})…` : undefined,
    }),
    [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, vec, designDiff, outputDesign, flattenChange, language],
  );

  return <AlgorithmApp id="copypaste-coord" label="Copy & Paste (Coord)" windows={WITH_COORD_WINDOWS} context={context} className="h-full w-full" />;
}

// #endregion WithCoord

const meta = {
  title: "semio-algorithms/CopyAndPaste",
  component: CopyAndPasteWithoutCoordFrame,
  parameters: { layout: "fullscreen" },
  tags: ["autodocs"],
} satisfies Meta;

export default meta;

type Story = StoryObj<typeof meta>;

export const WithoutCoord: Story = { render: () => <CopyAndPasteWithoutCoordFrame /> };
export const WithCoord: Story = { render: () => <CopyAndPasteWithCoordFrame /> };

