import { useAlgorithmLanguage } from "../withLanguage";

import metabolismKit from "../../../assets/semio/metabolism.kit.semio.json";

const nakaginCapsuleTowerDesignGuid = "9a890dd4-0a9c-48ac-920a-9e62666465ef";
const rawDesign = (metabolismKit.designs ?? []).find((d: any) => d.guid === nakaginCapsuleTowerDesignGuid) as any;

const WINDOWS: AlgorithmWindowDef[] = [
  { id: "copypaste-input", kind: WindowKind.SELECTION_INPUT, label: "Input" },
  { id: "copypaste-copy-output", kind: WindowKind.DESIGN_OUTPUT, label: "Copy Output" },
  { id: "copypaste-paste-diff", kind: WindowKind.DESIGN_DIFF_OUTPUT, label: "Paste Diff" },
  { id: "copypaste-paste-output", kind: WindowKind.DESIGN_OUTPUT, label: "Paste Output" },
];

function CopyAndPasteFrame() {
  const language = useAlgorithmLanguage() as NativeAlgorithmLanguage;
  const kit = metabolismKit as any;
  const [flattenChange, setFlattenChange] = React.useState<DesignChange | null>(null);
  const [baseDesign, setBaseDesign] = React.useState<any | null>(null);
  const [selectedPieceGuids, setSelectedPieceGuids] = React.useState<string[]>([]);
  const [selectedConnectionGuids, setSelectedConnectionGuids] = React.useState<string[]>([]);
  const [copyResult, setCopyResult] = React.useState<Design | undefined>(undefined);
  const [designDiff, setDesignDiff] = React.useState<any | undefined>(undefined);

  React.useEffect(() => {
    let cancelled = false;
    setFlattenChange(null);
    setBaseDesign(null);
    setDesignDiff(undefined);
    setCopyResult(undefined);
    void (async () => {
      const fc = await nativeFlattenDesign(kit, rawDesign.guid, language);
      if (cancelled) return;
      setFlattenChange(fc);
      const bd = applyDesignDiff(rawDesign, fc.forward) as any;
      setBaseDesign(bd);
      setSelectedPieceGuids((prev) => {
        const pieceGuids = new Set<string>((bd?.pieces ?? []).map((p: any) => p.guid));
        const filtered = prev.filter((g) => pieceGuids.has(g));
        if (filtered.length > 0) return filtered;
        return (bd?.pieces ?? []).slice(0, 3).map((piece: any) => piece.guid);
      });
    })();
    return () => {
      cancelled = true;
    };
  }, [kit, language]);

  React.useEffect(() => {
    if (!baseDesign) return;
    let cancelled = false;
    void (async () => {
      if (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) {
        if (!cancelled) {
          setCopyResult(undefined);
          setDesignDiff(undefined);
        }
        return;
      }
      setCopyResult(undefined);
      setDesignDiff(undefined);
      const copied = await nativeCopyDesign(kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, language);
      if (cancelled) return;
      setCopyResult(copied);
      const diff = await nativePasteDesign(kit, copied, baseDesign, "bottomLeft", undefined, language);
      if (!cancelled) setDesignDiff(diff);
    })();
    return () => {
      cancelled = true;
    };
  }, [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, language]);

  const outputDesign = React.useMemo(() => (designDiff && baseDesign ? applyDesignDiff(baseDesign, designDiff) : (baseDesign ?? rawDesign)), [designDiff, baseDesign]);

  const context: AlgorithmContextValue = React.useMemo(
    () => ({
      kit,
      design: baseDesign ?? rawDesign,
      selectedPieceGuids,
      onSelectedPieceGuidsChange: setSelectedPieceGuids,
      selectedConnectionGuids,
      onSelectedConnectionGuidsChange: setSelectedConnectionGuids,
      designDiff,
      outputDesign: copyResult ?? outputDesign,
      error: !flattenChange || !baseDesign ? `Loading copy & paste preview (${language})…` : (selectedPieceGuids.length === 0 && selectedConnectionGuids.length === 0) ? "Select at least one piece or connection to copy." : !copyResult ? `Loading copy result (${language})…` : !designDiff ? `Loading paste result (${language})…` : undefined,
    }),
    [kit, baseDesign, selectedPieceGuids, selectedConnectionGuids, copyResult, designDiff, outputDesign, flattenChange, language],
  );

  return <AlgorithmApp id="copypaste" label="Copy & Paste" windows={WINDOWS} context={context} className="h-full w-full" />;
}

const meta = {
  title: "semio-algorithms/CopyAndPaste",
  component: CopyAndPasteFrame,
  parameters: { layout: "fullscreen" },
  tags: ["autodocs"],
} satisfies Meta;

export default meta;

type Story = StoryObj<typeof meta>;

export const Default: Story = { render: () => <CopyAndPasteFrame /> };

